39		}
40		if memo == nil {
41			return nil, status.Errorf(codes.NotFound, "memo not found")
42		}
43		if memo.CreatorID != user.ID && !isSuperUser(user) {
44			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
45		}
46	
47		var expiresTs *int64
48		if request.MemoShare != nil && request.MemoShare.ExpireTime != nil {
49			ts := request.MemoShare.ExpireTime.AsTime().Unix()
50			if ts <= time.Now().Unix() {
51				return nil, status.Errorf(codes.InvalidArgument, "expire_time must be in the future")
52			}
53			expiresTs = &ts
54		}
